#!/usr/bin/env bash
# -----------------------------------------------------------------------------
# CGPA Pilot - v1.0.20 updater (Mac / Linux / WSL)
#
#   Double-click me, or in a terminal run:   bash apply-v1.0.20.sh
#
#   This file carries the whole v1.0.20 patch inside it. It will:
#     1. check you are inside the CGPA-pilot folder and main is up to date
#     2. refuse to run if you have OTHER uncommitted work (I never touch it)
#     3. apply the v1.0.20 patch, commit it, and push it to main
#
#   WHAT THIS ADDS (images out of the database - the "4 MB catalog" fix):
#     - R2 IMAGE STORAGE: every image you upload in the admin console now
#       goes to a Cloudflare R2 bucket, and the catalog keeps only a tiny
#       reference (asset:catalog/xxxx.png). The catalog no longer bloats
#       with base64 - your 4.0 MB catalog becomes a few hundred KB, and
#       the ~2 MB publish limit can no longer bite. (One-time setup below.)
#     - STORAGE VIEW: a new "Storage" page in the admin console shows
#       (1) how much your app's images use in R2, (2) how much of the
#       10 GB free tier is left, and (3) EVERY R2 bucket in your whole
#       Cloudflare account (your other projects included) - so you never
#       exceed the account limit. (3) needs a free read-only API token,
#       added on the page itself in 30 seconds.
#     - ONE-CLICK MIGRATION: the Storage page has a button that moves ALL
#       the images currently embedded in your catalog into R2 - run it
#       once, then Save & Publish.
#     - PUBLISH SIZE ALWAYS VISIBLE: next to "Save & Publish" there is now
#       a chip showing the EXACT size you are about to publish (green
#       under the limit, red over it), and the success toast repeats it.
#     - Graceful fallback: until the R2 bucket exists, everything keeps
#       working exactly as before (images stored in the catalog).
#
#   ONE-TIME SETUP AFTER RUNNING ME (about 5 minutes, then it's forever):
#     1. Cloudflare dashboard -> R2 object storage -> Create bucket ->
#        name it  cgpa-pilot-assets  (region: default).
#        (The new wrangler.toml already binds it as R2_ASSETS - the deploy
#        will fail until the bucket exists, which is the reminder.)
#     2. Let the Worker redeploy (your normal deploy/Workers Builds), and
#        let the site rebuild.
#     3. In the admin console open the new "Storage" page and press
#        "Move catalog images to R2", then "Save & Publish".
#     4. (Optional, for the whole-account view) on the same page add a
#        free API token: My Profile -> API Tokens -> Create token ->
#        "R2 Object Read Only" template, plus your Account ID.
#
#   Builds on v1.0.19 (catalog size visibility).
# -----------------------------------------------------------------------------
set -u
cd "$(dirname "$0")" || exit 1

echo "============================================"
echo " CGPA Pilot updater - v1.0.20"
echo " (images move to Cloudflare R2 + Storage"
echo "  monitor + always-visible publish size)"
echo "============================================"
echo
[ -f package.json ] || {
  echo " ERROR: put this file INSIDE your CGPA-pilot folder"
  echo " (the folder that contains package.json), then run it again."
  exit 1
}
command -v git >/dev/null 2>&1 || { echo " ERROR: git is not installed."; exit 1; }
echo " Repo folder: $PWD"
echo

# --- Safety: never touch other uncommitted work ---
# (old updater files v1.0.12-v1.0.20 are ignored - they are mine, not yours)
if [ -n "$(git status --porcelain | grep -v -e 'apply-v1.0.12.sh' -e 'fix-cgpa-v1.0.12.bat' -e 'v1.0.12.patch' -e '.v1012' -e 'apply-v1.0.13.sh' -e 'fix-cgpa-v1.0.13.bat' -e 'v1.0.13.patch' -e '.v1013' -e 'apply-v1.0.14.sh' -e 'fix-cgpa-v1.0.14.bat' -e 'v1.0.14.patch' -e '.v1014' -e 'apply-v1.0.15.sh' -e 'fix-cgpa-v1.0.15.bat' -e 'v1.0.15.patch' -e '.v1015' -e 'apply-v1.0.16.sh' -e 'v1.0.16.patch' -e '.v1016' -e 'apply-v1.0.17.sh' -e 'v1.0.17.patch' -e '.v1017' -e 'apply-v1.0.18.sh' -e 'v1.0.18.patch' -e '.v1018' -e 'apply-v1.0.19.sh' -e 'v1.0.19.patch' -e '.v1019' -e 'apply-v1.0.20.sh' -e 'v1.0.20.patch' -e '.v1020' | head -n 1)" ]; then
  echo " STOP - this folder has other uncommitted changes:"
  git status --short
  echo
  echo " I never touch your work. Commit or stash those first, then run me again."
  exit 1
fi

echo " Checking main is up to date..."
git checkout main || exit 1
git pull origin main || { echo; echo " Could not update from GitHub - check your internet connection."; exit 1; }

# --- Already applied? ---
if [ -f src/config/assets.ts ]; then
  echo
  echo " v1.0.20 is already applied - nothing to do. You are up to date."
  exit 0
fi

# --- This update builds on v1.0.19 (catalog size visibility) ---
if [ ! -f src/admin/catalogSize.ts ]; then
  echo
  echo ' This update builds on v1.0.19 (catalog size visibility).'
  echo ' Please run apply-v1.0.19.sh first (it is in this folder),'
  echo ' then run me again.'
  exit 1
fi

echo
echo " Preparing the v1.0.20 patch (embedded in this file)..."
rm -f .v1020.b64 .v1020.patch
